import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    aggregates = {"SUM", "MIN", "MAX"}
    functions = aggregates | {"IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        # Small chunks also support literals beyond Python's digit limit.
        text = text.strip()
        negative = text.startswith("-")
        if text[0] in "+-":
            text = text[1:]
        result = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            result = result * (10 ** len(chunk)) + int(chunk)
        return -result if negative else result

    def parse(formula):
        tokens = re.findall(
            r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]", formula
        )
        nodes = []
        operators = []

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        need_operand = True
        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token in functions:
                # A tuple marks parentheses and the start of call arguments.
                operators.append((token, len(nodes)))
                need_operand = True
                i += 2
                continue

            if token == "(":
                operators.append((None, len(nodes)))
                need_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                function, start = operators.pop()
                if function is not None:
                    args = tuple(nodes[start:])
                    del nodes[start:]
                    nodes.append((function, args))
                need_operand = False
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                need_operand = True
            elif token == "-" and need_operand:
                operators.append("neg")
            elif token in precedence:
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                need_operand = True
            else:
                nodes.append(
                    integer(token) if token[0].isdigit() else token
                )
                need_operand = False

            i += 1

        while operators:
            reduce_operator()
        return nodes[0]

    def expand_arguments(args):
        for arg in args:
            if isinstance(arg, tuple) and arg[0] == ":":
                first, last = arg[1], arg[2]
                left, right = sorted((ord(first[0]), ord(last[0])))
                top, bottom = sorted((int(first[1:]), int(last[1:])))
                for row in range(top, bottom + 1):
                    suffix = str(row)
                    for col in range(left, right + 1):
                        name = chr(col) + suffix
                        if name in cells:
                            yield name
            else:
                yield arg

    memo = {}
    active = set()

    # Explicit continuations avoid recursion limits for formulas and cell chains.
    for root in cells:
        if root in memo:
            continue

        stack = [("cell", root)]
        value = 0

        while stack:
            task = stack.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    value = 0
                elif name in memo:
                    value = memo[name]
                elif name in active:
                    value = "#CYCLE!"
                else:
                    active.add(name)
                    content = cells[name]
                    node = (
                        parse(content[1:])
                        if content.startswith("=")
                        else integer(content)
                    )
                    stack.append(("finish", name))
                    stack.append(("expr", node))

            elif kind == "finish":
                name = task[1]
                memo[name] = value
                active.remove(name)

            elif kind == "expr":
                node = task[1]
                if isinstance(node, int):
                    value = node
                elif isinstance(node, str):
                    stack.append(("cell", node))
                else:
                    op = node[0]
                    if op == "neg":
                        stack.append(("negate",))
                        stack.append(("expr", node[1]))
                    elif op == "IF":
                        condition, then_branch, else_branch = node[1]
                        stack.append(("choose", then_branch, else_branch))
                        stack.append(("expr", condition))
                    elif op in aggregates:
                        args = expand_arguments(node[1])
                        stack.append(("next_arg", op, args, None))
                    else:
                        stack.append(("left_done", op, node[2]))
                        stack.append(("expr", node[1]))

            elif kind == "negate":
                if not isinstance(value, str):
                    value = -value

            elif kind == "choose":
                if not isinstance(value, str):
                    branch = task[1] if value else task[2]
                    stack.append(("expr", branch))

            elif kind == "left_done":
                if not isinstance(value, str):
                    stack.append(("right_done", task[1], value))
                    stack.append(("expr", task[2]))

            elif kind == "right_done":
                if isinstance(value, str):
                    continue

                op, left = task[1], task[2]
                right = value

                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        value = (
                            -quotient
                            if (left < 0) != (right < 0)
                            else quotient
                        )
                elif op == "=":
                    value = left == right
                elif op == "<>":
                    value = left != right
                elif op == "<":
                    value = left < right
                elif op == "<=":
                    value = left <= right
                elif op == ">":
                    value = left > right
                elif op == ">=":
                    value = left >= right

            elif kind == "next_arg":
                op, args, accumulated = task[1:]
                try:
                    node = next(args)
                except StopIteration:
                    value = 0 if accumulated is None else accumulated
                else:
                    stack.append(("collect", op, args, accumulated))
                    stack.append(("expr", node))

            elif kind == "collect":
                if isinstance(value, str):
                    continue

                op, args, accumulated = task[1:]
                if accumulated is None:
                    accumulated = value
                elif op == "SUM":
                    accumulated += value
                elif op == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                stack.append(("next_arg", op, args, accumulated))

    return {name: memo[name] for name in cells}
